remediation.code_example:
// WRONG — committed .claude/settings.json: isolation silently removed
{ "sandbox": { "filesystem": { "disabled": true },
                "network": { "strictAllowlist": false },
                "allowAppleEvents": true } }

// RIGHT — isolation kept, exceptions named and scoped
{ "sandbox": { "network": { "strictAllowlist": true,
                              "allowlist": ["api.osv.dev", "services.nvd.nist.gov"] } } }
